function compute(inputs, t) {
  const g = 9.81, start = 20 * Math.PI / 180;
  const swing = (length, pivotX) => {
    const period = 2 * Math.PI * Math.sqrt(length / g);
    const angle = start * Math.cos(2 * Math.PI * t / period);
    return { period, degrees: angle * 180 / Math.PI, x: pivotX + length * Math.sin(angle), y: -length * Math.cos(angle) };
  };
  const a = swing(1, -0.7), b = swing(inputs.lengthB, 0.7);
  return {
    periodA: a.period, periodB: b.period, angleA: a.degrees, angleB: b.degrees,
    bobAx: a.x, bobAy: a.y, bobBx: b.x, bobBy: b.y,
    sizeB: (inputs.massB - 0.5) / 2.5,
    sameLength: Math.abs(inputs.lengthB - 1) < 1e-9 && Math.abs(inputs.massB - 1) > 1e-9,
    longer: inputs.lengthB > 1 + 1e-9,
    shorter: inputs.lengthB < 1 - 1e-9
  };
}

function compute(inputs, t) {
  const g = inputs.planet === 'mars' ? 3.71 : 9.81;
  const tilt = inputs.launchAngle * Math.PI / 180;
  const across = inputs.speed * Math.cos(tilt), up = inputs.speed * Math.sin(tilt);
  const flightTime = 2 * up / g, now = Math.min(t, flightTime);
  const ballX = across * now, ballY = Math.max(0, up * now - g * now * now / 2);
  const upNow = t < flightTime ? up - g * now : 0, acrossNow = t < flightTime ? across : 0;
  return { ballX, ballY, tipX: ballX + 0.2 * acrossNow, tipY: ballY + 0.2 * upNow,
    range: across * flightTime, peak: up * up / (2 * g), flightTime, landed: t >= flightTime };
}

function compute(inputs, t) {
  const scores = [2.0, 1.0, 0.5, -1.0];
  const weights = scores.map(score => Math.exp(score / inputs.temperature));
  const total = weights.reduce((sum, weight) => sum + weight, 0);
  const probs = weights.map(weight => weight / total);
  return { probs, topProb: probs[0], lastProb: probs[3], sharp: inputs.temperature < 0.6, flat: inputs.temperature > 2 };
}

function compute(inputs, t) {
  const words = ['The', 'cat', 'sat', 'on', 'the', 'mat'];
  const scores = [[2.0, 1.8, 0.4, 0.1, 0.3, 0.2], [1.5, 2.0, 1.0, 0.1, 0.2, 0.6], [0.2, 2.2, 1.8, 0.8, 0.1, 0.9], [0.1, 0.5, 1.6, 1.4, 0.6, 1.9], [0.4, 0.1, 0.5, 1.0, 1.2, 2.1], [0.1, 0.9, 0.8, 1.5, 1.3, 2.0]];
  const softmax = row => { const w = row.map(Math.exp), sum = w.reduce((a, b) => a + b, 0); return w.map(v => v / sum); };
  const all = scores.map(softmax), weights = all[inputs.word];
  const top = weights.indexOf(Math.max(...weights));
  return { all, weights, top, topWeight: weights[top], pickedWord: words[inputs.word], topWord: words[top], toItself: top === inputs.word };
}

function compute(inputs, t) {
  const loss = x => x * x, slope = x => 2 * x;
  let position = inputs.start;
  for (let step = 0; step < t; step++) position = position - inputs.rate * slope(position);
  return { position, loss: loss(position), curve: loss(inputs.x), step: t,
    tipX: position - inputs.rate * slope(position), tooFast: inputs.rate > 1, crawling: inputs.rate < 0.1 };
}

function compute(inputs, t) {
  const starts = { shuffled: [4, 2, 6, 1, 5, 3], reversed: [6, 5, 4, 3, 2, 1], nearly: [1, 2, 4, 3, 5, 6] };
  const items = starts[inputs.order].slice();
  let swaps = 0, done = 0, pair = [0, 1], sortedFrom = items.length;
  for (let pass = 0; pass < items.length - 1; pass++) {
    for (let j = 0; j < items.length - 1 - pass; j++) {
      pair = [j, j + 1];
      if (done === t) return result();
      if (items[j] > items[j + 1]) { const keep = items[j]; items[j] = items[j + 1]; items[j + 1] = keep; swaps++; }
      done++;
    }
    sortedFrom = items.length - 1 - pass;
  }
  sortedFrom = 0;
  return result();
  function result() {
    let outOfOrder = 0;
    for (let k = 0; k < items.length - 1; k++) if (items[k] > items[k + 1]) outOfOrder++;
    return { heights: items.slice(), compared: pair.slice(), swaps, outOfOrder, sortedFrom, sorted: outOfOrder === 0, step: t };
  }
}

function compute(inputs, t) {
  let pieces = inputs.word.split(''), merged = '';
  for (let step = 0; step < t; step++) {
    const counts = {};
    for (let k = 0; k < pieces.length - 1; k++) { const pair = pieces[k] + ' ' + pieces[k + 1]; counts[pair] = (counts[pair] || 0) + 1; }
    let best = '', most = 1;
    for (const pair in counts) if (counts[pair] > most) { most = counts[pair]; best = pair; }
    if (!best) { merged = ''; break; }
    const [left, right] = best.split(' '), next = [];
    for (let k = 0; k < pieces.length; k++) {
      if (k < pieces.length - 1 && pieces[k] === left && pieces[k + 1] === right) { next.push(left + right); k++; } else next.push(pieces[k]);
    }
    pieces = next; merged = left + right;
  }
  return { pieces, xs: pieces.map((piece, k) => k * 1.2), count: pieces.length, merged: merged || 'none', nothingLeft: t > 0 && merged === '' };
}
